// Test-only shim. The browser resolves 'three' through the import map in
// index.html to the vendored build; node has no import map, and the sky
// maths only ever touches Vector3. Everything else is referenced inside
// buildSky(), which the maths tests never call.
export class Vector3 {
  constructor(x = 0, y = 0, z = 0) { this.x = x; this.y = y; this.z = z; }
  dot(v) { return this.x * v.x + this.y * v.y + this.z * v.z; }
  length() { return Math.sqrt(this.dot(this)); }
  angleTo(v) {
    const d = this.dot(v) / (this.length() * v.length());
    return Math.acos(Math.max(-1, Math.min(1, d)));
  }
}
